//! Bounded source-consumer qualification, independently regenerated by
//! qualify_goth_effect_calls.py from the original instruction trace and data.
//! This descriptor never turns an unavailable reached service into success.
use super::{Context, Result, Saved, Value, ensure};

pub struct InactiveEffects {
    source: Value,
}
impl InactiveEffects {
    pub fn import(source: Value) -> Result<Self> {
        ensure!(
            source["schema"] == 1
                && source["status"] == "inactive_effect_consumers_qualified"
                && source["source_report_sha256"]
                    == "d241a655ea5bde58100927aaea95994311097e93847544c675c5ecb92e34471e"
                && source["decoded_pc_payload_sha256"]
                    == "abd3d875cda21f17fa0139261a4d9a39a7243a65a172b322bcf58450cbe0fbd0"
                && source["instruction_image_sha256"]
                    == "a4d9f7134f52a186685961800608af72c23036ba62637eb9a99d75d4c5b1b321"
                && source["source_mutated"] == false
                && source["target_executed"] == false,
            "effect qualification source differs"
        );
        let rows = source["facts"]["consumers"]
            .as_array()
            .context("native effect consumers absent")?;
        let expected = [
            0x4a69aa, 0x4a698d, 0x4d322c, 0x588080, 0x584898, 0x57a54c, 0x452822,
        ];
        ensure!(
            rows.len() == expected.len()
                && rows
                    .iter()
                    .zip(expected)
                    .all(|(r, entry)| r["entry"] == entry
                        && r["instruction_visits"] == 0
                        && r["instruction_sites"].as_u64().is_some_and(|n| n > 0)),
            "original executes or lacks a qualified effect consumer"
        );
        let inputs = source["facts"]["inputs"]
            .as_array()
            .context("native effect inputs absent")?;
        ensure!(
            inputs.len() == 2 && source["facts"]["display_animation_names"] == false,
            "effect input profile differs"
        );
        for (input, (cut, tick)) in inputs.iter().zip([("before", 88448), ("after", 88449)]) {
            let people = input["person_notification_values"]
                .as_object()
                .context("native notification cohort absent")?;
            ensure!(
                input["cut"] == cut
                    && input["tick"] == tick
                    && people.len() == 3
                    && ["16", "18", "21"]
                        .iter()
                        .all(|&id| people.get(id) == Some(&Value::from(0))),
                "original has pending person notification work"
            );
        }
        Ok(Self { source })
    }
    pub fn require_current_inputs(&self, saved: &Saved) -> Result<()> {
        ensure!(
            [88448, 88449].contains(&saved.simulation.state.vm.tick),
            "effect proof outside captured interval"
        );
        let s = &saved.simulation.state;
        let people: Vec<_> =
            s.vm.world
                .objects
                .iter()
                .filter(|(_, o)| o.person.is_some())
                .collect();
        ensure!(
            people.iter().map(|(id, _)| **id).eq([16, 18, 21])
                && people
                    .iter()
                    .all(|(_, o)| o.person.as_ref().unwrap().get(&1) == Some(&0)),
            "current person notification input differs from inactive native proof"
        );
        ensure!(
            !s.native_character_settings
                .as_ref()
                .context("native person settings absent")?
                .person
                .display_animation_names,
            "animation notification renderer is required"
        );
        ensure!(
            saved.assets.notification_jobs.is_empty()
                && s.characters.values().all(|r| r
                    .person_update
                    .as_ref()
                    .is_none_or(|p| !p.notification_started)),
            "unbound notification renderer has an accepted caller"
        );
        ensure!(
            s.vm.sounds.is_empty() && s.vm.effects.is_empty(),
            "headless effect outputs require an original comparison"
        );
        Ok(())
    }
    pub fn source(&self) -> &Value {
        &self.source
    }
}
